function supplierFigures(supplierId){const invoices=state.documents.filter(x=>x.documentType==='purchase'&&x.supplierId===supplierId),settlements=state.reports.settlements||[];const total=invoices.reduce((s,x)=>s+Number(x.grossAmount||x.subtotal||0),0),discount=invoices.reduce((s,x)=>s+Number(x.discountAmount||0),0),deposit=invoices.reduce((s,x)=>s+Number(x.paidAmount||0),0),later=invoices.reduce((s,x)=>s+settlements.filter(y=>y.documentId===x.id).reduce((a,y)=>a+Number(y.amount||0),0),0),remaining=invoices.reduce((s,x)=>s+Math.max(0,outstanding(x)),0);return{invoices,total,discount,deposit,received:deposit+later,remaining};}
