function supplierLedger(supplierId=''){const suppliers=state.master.suppliers||[],selected=supplierId?suppliers.filter(x=>x.id===supplierId):suppliers,rows=[];for(const supplier of selected){const invoices=state.documents.filter(x=>x.documentType==='purchase'&&x.supplierId===supplier.id);for(const invoice of invoices){rows.push({at:invoice.occurredAt||invoice.createdAt,supplier:supplier.name,kind:'فاتورة مشتريات',reference:invoice.documentNumber,debit:Number(invoice.subtotal||0),credit:0,details:`الإجمالي ${money(invoice.grossAmount||invoice.subtotal)} · الخصم ${money(invoice.discountAmount)}`});if(Number(invoice.paidAmount)>0)rows.push({at:invoice.occurredAt||invoice.createdAt,supplier:supplier.name,kind:'عربون الفاتورة',reference:invoice.documentNumber,debit:0,credit:Number(invoice.paidAmount),details:'دفع أولي'});for(const p of (state.reports.settlements||[]).filter(x=>x.documentId===invoice.id))rows.push({at:p.occurredAt,supplier:supplier.name,kind:p.method==='cash'?'دفع نقدي':p.method==='check'?'صك':'حوالة مصرفية',reference:p.receiptNumber,debit:0,credit:Number(p.amount),details:[p.bankName,p.transactionNumber].filter(Boolean).join(' · ')||'نقدي'});}}rows.sort((a,b)=>String(a.at).localeCompare(String(b.at)));let balance=0;return rows.map(x=>({...x,balance:balance+=x.debit-x.credit}));}
