function scaled(value){const normalized=normalizeNumberText(value);if(!/^\d+(\.\d{1,6})?$/.test(normalized))throw Error('قيمة غير صالحة؛ اكتب الأرقام مع نقطة أو فاصلة عشرية، وبحد أقصى ست منازل');const [a,b='']=normalized.split('.');return BigInt(a)*1000000n+BigInt(b.padEnd(6,'0'));}
