function total(){return state.lines.reduce((sum,line)=>sum+(scaled(line.quantity)*scaled(line.unitPrice)+500000n)/1000000n,0n);}
function renderLines(){if(state.view==='purchase')$('lineTable').innerHTML='<div class="purchase-lines">'+(state.lines.map((x,i)=>{const item=state.master.items.find(row=>row.id===x.itemId)||{},s=x.specifications||{};return `<article><header><div><strong>${i+1}. ${escape(s.tradeName||item.name)}</strong><small>Item: ${escape(s.itemNumber||item.sku)} · المنشأ ${escape(s.originCountry||'—')} · المعمل ${escape(s.factory||'—')} · القياسات ${escape(s.dimensions||'—')} · الألوان ${escape(s.colors||'—')}</small></div><button type="button" class="secondary" data-remove="${i}">حذف</button></header><div><span>العدد <b>${money(x.quantity)}</b></span><span>سعر الشراء <b>${money(x.purchasePrice)}</b></span><span>الإضافة <b>${money(x.addition)}</b></span><span>الشراء النهائي <b>${money(x.unitPrice)}</b></span><span>بيع جملة <b>${money(x.wholesalePrice)}</b></span><span>بيع مفرد <b>${money(x.retailPrice)}</b></span><span class="purchase-line-total">إجمالي المادة <b>${money(decimal((scaled(x.quantity)*scaled(x.unitPrice)+500000n)/1000000n))}</b></span></div>${x.note?`<p class="purchase-note"><b>ملاحظة المادة:</b> ${escape(x.note)}</p>`:''}</article>`;}).join('')||'<p class="empty">أضف المادة الأولى إلى الفاتورة.</p>')+'</div>';else $('lineTable').innerHTML=table(['الصنف','الوحدة','الكمية','السعر','المجموع',''],state.lines.map((x,i)=>[name(state.master.items,x.itemId),name(state.master.units,x.unitId),money(x.quantity),money(x.unitPrice),money(decimal((scaled(x.quantity)*scaled(x.unitPrice)+500000n)/1000000n)),`<button type="button" class="secondary" data-remove="${i}">حذف البند</button>`]));$('documentTotal').textContent='إجمالي فاتورة المشتريات: '+money(decimal(total()))+' '+currencyLabel();$('lineTable').querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>{state.lines.splice(Number(button.dataset.remove),1);renderLines();});}
function unitOptions(){const item=state.master.items.find(x=>x.id===$('lineItem').value);$('lineUnit').innerHTML=(item?.units||[]).map(x=>`<option value="${escape(x.unitId)}">${name(state.master.units,x.unitId)}</option>`).join('');setPrice();}
