 const journalLines=$('journalLines');if(journalLines){const accounts=state.reports.chartAccounts||[];const addLine=()=>{const row=document.createElement('div');row.className='journal-row';row.style.cssText='display:grid;grid-template-columns:minmax(150px,2fr) 1fr 1fr auto;gap:8px;margin:8px 0';row.innerHTML='<select data-account aria-label="الحساب">'+accounts.filter(a=>a.active!==false).map(a=>'<option value="'+escape(a.code)+'">'+escape(a.code)+' — '+escape(a.name)+'</option>').join('')+'</select><input data-debit type="text" inputmode="decimal" lang="en" dir="ltr" class="decimal-entry" data-decimal-input="true" value="0" aria-label="مدين" placeholder="مدين"><input data-credit type="text" inputmode="decimal" lang="en" dir="ltr" class="decimal-entry" data-decimal-input="true" value="0" aria-label="دائن" placeholder="دائن"><button type="button" class="secondary" data-remove>حذف</button>';row.querySelector('[data-remove]').onclick=()=>{if(journalLines.children.length>2){row.remove();updateBalance();}};row.oninput=updateBalance;journalLines.append(row);updateBalance();};const updateBalance=()=>{const rows=[...journalLines.querySelectorAll('.journal-row')],d=rows.reduce((n,r)=>n+numericValue(r.querySelector('[data-debit]').value||0),0),c=rows.reduce((n,r)=>n+numericValue(r.querySelector('[data-credit]').value||0),0);$('journalBalance').textContent='إجمالي المدين: '+money(d)+' | إجمالي الدائن: '+money(c)+' | الفرق: '+money(d-c);};$('addJournalLine').onclick=addLine;addLine();addLine();}
  const journal=$('manualJournal');if(journal)journal.onsubmit=e=>{e.preventDefault();busy(journal,async()=>{const v=Object.fromEntries(new FormData(journal)),lines=[...journal.querySelectorAll('.journal-row')].map(row=>({accountCode:row.querySelector('[data-account]').value,debit:normalizeNumberText(row.querySelector('[data-debit]').value||'0'),credit:normalizeNumberText(row.querySelector('[data-credit]').value||'0')}));const debit=lines.reduce((n,x)=>n+numericValue(x.debit),0),credit=lines.reduce((n,x)=>n+numericValue(x.credit),0);if(lines.length<2||debit<=0||Math.abs(debit-credit)>0.000001)throw Error('يجب تساوي إجمالي المدين والدائن قبل الترحيل');if(lines.some(x=>(numericValue(x.debit)>0)===(numericValue(x.credit)>0)))throw Error('كل طرف يجب أن يكون مدينًا أو دائنًا فقط');await api('/api/v1/accounting/journals',{operationId:crypto.randomUUID(),entryNumber:v.entryNumber,occurredAt:new Date(v.occurredAt).toISOString(),description:v.description,currency:state.account.company.currency,lines});await refresh();notify('تم ترحيل القيد بنجاح');});};
