 $('loadForm')?.addEventListener('submit',event=>{event.preventDefault();busy(event.target,async()=>{const data=Object.fromEntries(new FormData(event.target));await api('/api/v1/sales/'+encodeURIComponent(data.documentId)+'/loads',{operationId:crypto.randomUUID(),loadNumber:data.loadNumber,lines:[{originalLineId:data.originalLineId,quantity:data.quantity}]});await refresh();notify('تم تسجيل التحميل الجزئي وربطه بفاتورة البيع');});});
 function settlementConversion(form){
 const doc=state.documents.find(x=>x.id===form.documentId.value),received=numericValue(form.receivedAmount.value||0),rate=numericValue(form.exchangeRate.value||0),rc=form.receivedCurrency.value,dc=doc?.currency||currencyCode();
 let amount=received;if(rc!==dc){if(!(rate>0)){form.amount.value='';return;}amount=dc==='USD'?received/rate:received*rate;}
 form.amount.value=Number.isFinite(amount)?amount.toFixed(6):'';
}
