 if($('commerce')){
  $('lineItem').onchange=unitOptions;$('lineUnit').onchange=setPrice;unitOptions();
  $('addLine').onclick=()=>{try{if(!$('lineItem').value||!$('lineUnit').value)throw Error('عرّف الصنف ووحدته أولًا');const quantity=normalizeNumberText($('lineQty').value),purchasePrice=normalizeNumberText($('linePrice').value),addition=state.view==='purchase'?normalizeNumberText($('lineAddition').value):'0',unitPrice=decimal(scaled(purchasePrice)+scaled(addition));if(scaled(quantity)<=0n)throw Error('الكمية أكبر من صفر');scaled(unitPrice);const specifications=state.view==='purchase'?{itemNumber:$('lineItemNumber').value.trim(),tradeName:$('lineTradeName').value.trim(),originCountry:$('lineOriginCountry').value.trim(),factory:$('lineFactory').value.trim(),dimensions:$('lineDimensions').value.trim(),colors:$('lineColors').value.trim()}:{};state.lines.push({itemId:$('lineItem').value,unitId:$('lineUnit').value,quantity,unitPrice,purchasePrice,addition,wholesalePrice:normalizeNumberText($('lineWholesale')?.value||'0'),retailPrice:normalizeNumberText($('lineRetail')?.value||'0'),specifications,note:state.view==='purchase'?$('lineNote').value.trim():'',originalLineId:null});if($('lineNote'))$('lineNote').value='';renderLines();}catch(error){notify(error.message);}};
  $('commerce').onsubmit=async event=>{event.preventDefault();await busy(event.target,async()=>{if(!state.lines.length)throw Error('أضف بندًا واحدًا على الأقل');const data=Object.fromEntries(new FormData(event.target));const amount=total();const paid=data.paymentMode==='cash'?amount:data.paymentMode==='mixed'?scaled(data.paid):0n;if(paid>amount)throw Error('المدفوع يتجاوز إجمالي الفاتورة');if(paid<amount&&!data.partyId)throw Error('اختر العميل أو المورد للفاتورة الآجلة');const document={documentType:state.view,documentNumber:data.documentNumber,warehouseId:data.warehouseId,partyId:data.partyId||null,currency:data.currency||currencyCode(),note:data.note||'',lines:state.lines.map(({itemId,unitId,quantity,unitPrice,specifications,note,originalLineId})=>({itemId,unitId,quantity,unitPrice,specifications,note,originalLineId})),payments:paid?[{method:'cash',amount:decimal(paid),reference:null}]:[]};await commit(document);if(state.view==='purchase')for(const line of state.lines)for(const [priceType,amount] of [['purchase',line.unitPrice],['sale_wholesale',line.wholesalePrice],['sale_retail',line.retailPrice]])await api('/api/v1/catalog/prices',{itemId:line.itemId,unitId:line.unitId,priceType,currency:data.currency||currencyCode(),amount});state.lines=[];await refresh();notify('تم اعتماد الفاتورة وترحيل المخزون وتحديث أسعار الشراء والبيع');});};
 }
