async function busy(form,action){const buttons=[...form.querySelectorAll('button')];buttons.forEach(x=>x.disabled=true);try{await action();}catch(error){notify(error.message);}finally{buttons.forEach(x=>x.disabled=false);}}
async function commit(document){const body={operationId:crypto.randomUUID(),deviceId:'enterprise-desktop',clientSequence:Date.now(),occurredAt:new Date().toISOString(),document};const result=await api('/api/v1/commerce/commit',body);if(result.result.status!=='acknowledged')throw Error(result.result.error?.message||'لم يعتمد المستند');}
function showDocument(id){const document=state.documents.find(x=>x.id===id);if(!document)return;state.selected=document;$('documentDetail').innerHTML=`<h1>${escape(state.account.company.legalName)}</h1><h2>${escape(types[document.documentType])} · ${escape(document.documentNumber)}</h2><p>${escape(document.occurredAt||'')}</p>${document.note?`<p><b>ملاحظات الفاتورة:</b> ${escape(document.note)}</p>`:''}`+table(['رقم Item','الاسم التجاري والمواصفات','العدد','السعر','المجموع','الملاحظات'],document.lines.map(x=>{const item=state.master.items.find(i=>i.id===x.itemId),s=x.specifications||{};return[escape(s.itemNumber||item?.sku),`${escape(s.tradeName||item?.name)}<br><small>دولة المنشأ: ${escape(s.originCountry||'—')} · المعمل: ${escape(s.factory||'—')} · القياسات: ${escape(s.dimensions||'—')} · الألوان: ${escape(s.colors||'—')}</small>`,money(x.quantity),money(x.unitPrice),money(x.subtotal||x.lineTotal),escape(x.note||'—')];}))+`<h2>الإجمالي: ${money(document.subtotal)} ${currencyLabel()}</h2><p>المدفوع: ${money(document.paidAmount)} · المتبقي: ${money(document.dueAmount)}</p>`;$('returnDocument').hidden=document.documentType.endsWith('_return');$('documentDialog').showModal();}
function exportStock(){const rows=[['المخزن','كود Item','الصنف','الكمية','التكلفة'],...(state.master.stock||[]).map(x=>{const item=state.master.items.find(i=>i.id===x.itemId);return[state.master.warehouses.find(w=>w.id===x.warehouseId)?.name,item?.sku,item?.name,x.quantity,x.averageCost];})];const csv='\uFEFF'+rows.map(row=>row.map(value=>'"'+String(value??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download='enterprise-stock.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}
function go(view){if(!allowedView(view)){notify('لا توجد صلاحية لهذا القسم');return;}if(state.lines.length&&['sale','purchase'].includes(state.view)&&view!==state.view&&!confirm('مغادرة الفاتورة غير المعتمدة وحذف بنودها؟'))return;if(view!==state.view)state.lines=[];state.view=view;render();if(view==='marketPrices')void loadMarketFx();else clearTimeout(marketFxTimer);}
window.AlMahasibReadPageContext=function(){
 if(!state.account||!state.account.permissions.includes('assistant.use'))throw Error('لا تملك صلاحية استخدام المساعد الذكي');
 const documentOpen=$('documentDialog')?.open===true,source=documentOpen?$('documentDetail'):$('content');
 if(!source||!allowedView(state.view))throw Error('لا تملك صلاحية قراءة هذا القسم');
 const visible=element=>!element.closest('[hidden]')&&getComputedStyle(element).display!=='none'&&getComputedStyle(element).visibility!=='hidden';
 const lines=[String(source.innerText||'').trim()];
 const controls=[...source.querySelectorAll('input,textarea,select')].filter(element=>visible(element)&&!['hidden','password','file','checkbox','radio'].includes(element.type)&&!/pass|password|token|secret|csrf/i.test(element.name||''));
 for(const element of controls){
  const value=element instanceof HTMLSelectElement?element.selectedOptions[0]?.textContent:element.value;
  if(!String(value||'').trim())continue;
  const label=element.labels?.[0]?.innerText?.trim()||element.closest('label')?.innerText?.replace(String(value),'').trim()||element.name||'حقل';
  lines.push(label+': '+String(value).trim());
 }
 const title=documentOpen?$('documentDetail')?.querySelector('h2')?.innerText:titles[state.view];
 return {view:documentOpen?'documents':state.view,title:String(title||$('pageTitle')?.textContent||'').slice(0,120),content:lines.join('\n').slice(0,10000),scope:!documentOpen&&['sale','purchase'].includes(state.view)&&state.lines.length?'draft_invoice':'page'};
};
async function enter(){state.account=await api('/api/v1/bootstrap');startPresenceUpdates();if(isSalesRepresentative()||state.account.salesProfile?.salesManager)state.view='sale';$('backup').hidden=!state.local||!state.account.permissions.includes('company.manage');$('companyName').textContent=state.account.company.legalName;$('userName').textContent=state.account.user.displayName||'المستخدم';$('userLoginName').textContent=state.account.user.username?'@'+state.account.user.username:'';const activeRoles=(state.account.roles||[]).map(role=>roleNames[role.code]||role.name||role.code);$('toolbarRole').textContent='الصلاحية: '+(activeRoles.join('، ')||'غير محددة');window.dispatchEvent(new CustomEvent('almahasib:assistant-session',{detail:{companyId:state.account.company.id,userId:state.account.user.id}}));localStorage.setItem('almahasib_company_context',JSON.stringify({id:state.account.company.id,code:state.account.company.code,name:state.account.company.legalName}));$('entry').hidden=true;$('workspace').hidden=false;try{await refresh();}catch(error){notify('دخلت إلى الشركة، لكن تعذر تحميل بعض البيانات: '+error.message);state.view='overview';try{render();}catch{}}}
