function updateLoginClock(){const now=new Date(),date=now.toLocaleDateString('ar-IQ',{timeZone:'Asia/Baghdad',weekday:'short',year:'numeric',month:'short',day:'numeric'}),time=now.toLocaleTimeString('en-GB',{timeZone:'Asia/Baghdad',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});const loginClock=$('loginClock');if(loginClock)loginClock.textContent='التاريخ: '+date+' · الوقت: '+time;const toolbarDate=$('toolbarDate'),toolbarTime=$('toolbarTime');if(toolbarDate)toolbarDate.textContent=date;if(toolbarTime)toolbarTime.textContent=time;}
